"""Encode actual browser frames with original VFR timestamps; never insert/retime frames."""
from pathlib import Path
import json,subprocess,hashlib,statistics,sys
R=Path(__file__).resolve().parents[1];Q=R/'docs/v8-city/quality';mode=sys.argv[1];assert mode in ['v8-city-walkthrough'];j=json.loads((Q/(mode+'-capture.json')).read_text());assert not j['failure']and not j['errors'];delivery=j['frames'];out_of_order=sum(b['timestamp']<=a['timestamp'] for a,b in zip(delivery,delivery[1:]));frames=sorted(delivery,key=lambda f:f['timestamp']);assert len(frames)>300
first=frames[0]['timestamp'];stamps=[f['timestamp']-first for f in frames];assert all(b>a for a,b in zip(stamps,stamps[1:]))
for f in frames:assert hashlib.sha256((R/f['file']).read_bytes()).hexdigest()==f['sha256']
