probe=['ffprobe','-v','error','-select_streams','v:0','-show_entries','frame=best_effort_timestamp_time','-of','json'];encoded=json.loads(subprocess.check_output([*probe,str(mp4)]));pts=[float(x['best_effort_timestamp_time'])for x in encoded['frames']];assert len(pts)==len(stamps),(len(pts),len(stamps));error=max(abs((a-pts[0])-b)for a,b in zip(pts,stamps));assert error<=.002,error
meta=json.loads(subprocess.check_output(['ffprobe','-v','error','-select_streams','v:0','-count_frames','-show_entries','stream=codec_name,width,height,nb_read_frames,avg_frame_rate:format=duration,size','-of','json',str(mp4)]));duration=float(meta['format']['duration'])
report={'status':'PASS','method':'Actual full-browser CDP JPEG frames to H264 VFR; absolute original timestamps quantized to1ms BEFORE deriving duration differences, preventing accumulated rounding drift; option framerate1000 provides1ms input timebase; explicit encoder/container1/1000; no fps filter, interpolation, duplication, captured-frame removal or speed changes. Browser source capture sampled every second rendered frame via CDP; every captured frame is retained. H264 is lossy; native PNGs are the sharpness evidence. One real whole-browser stream per clip; no independent native stream claimed.','command':cmd,'deliveryOrderInversions':out_of_order,'timelineOrder':'All original frames sorted by their unchanged CDP capture timestamps, not delivery order. Original delivery list retained in capture.json.','maxVideoRateKbps':rate_kbps,'sourceWholeBrowserFrames':len(frames),'encodedWholeBrowserFrames':len(pts),'maxRelativeTimestampErrorSeconds':error,'encodedDurationSeconds':duration,'actualEncodedAverageFPS':len(pts)/duration,'sourceAverageFirstLastFPS':j['sourceWholeBrowserAverageFPS'],'mp4Sha256':hashlib.sha256(mp4.read_bytes()).hexdigest(),'mp4Bytes':mp4.stat().st_size,'rawJPEGRetention':'Ignored execution cache only; every original source frame timestamp/hash is checkpointed in capture.json, the encoded MP4 is checkpointed.','runtimeDuringCapture':j['runtime'],'visits':len(j['visits']),'errors':j['errors']}
